/**
 * 无边框主题配置
 * 该主题用于完全禁用流光边框与发光效果
 */
const NONE_THEME = {
  name: 'none',
  displayName: '无边框',
  borderGradients: [],
  baseBorderColor: 'transparent',
  glowColors: []
};

/**
 * 所有可用主题
 */
const GLOW_THEMES = {
  rainbow: RAINBOW_THEME,
  silver: SILVER_THEME,
  gold: GOLD_THEME,
  black: BLACK_THEME,
  none: NONE_THEME
};

/**
 * 默认主题
 */
const DEFAULT_THEME = 'gold';

/**
 * 根据 importance level 获取对应的主题
 * @param {number} importanceLevel - 重要级别 (1, 2, 3)
 * @returns {string} 主题名称(silver/gold/rainbow/none)
 */
function getThemeByImportanceLevel(importanceLevel) {
  switch (importanceLevel) {
    case 3:
      return 'silver';
    // 最重要
    case 2:
      return 'silver';
    // 中等重要 
    case 1:
      return 'silver';
    // 一般重要 
    default:
      return 'gold';
  }
}

/**
 * 生成边框层的background CSS
 * @param {Object} theme - 主题配置
 * @param {string} cardBg - 卡片内部背景色
 * @returns {string} CSS background 属性值
 */
function generateBorderBackground(theme, cardBg = 'rgba(255, 255, 255, 1.0)') {
  // 无边框主题：直接不绘制任何背景
  if (theme && theme.name === 'none') {
    return 'none';
  }
  const gradients = [];

  // 1. 内部背景（padding-box）：填充卡片内容背景，不被遮罩截断
  // 注意：这层会被 mask 的 exclude 操作移除，只是为了确保内容区域不透明
  gradients.push(`linear-gradient(${cardBg} 0 100%) padding-box`);

  // 2. 多色径向渐变（border-box）：仅当 theme.borderGradients 非空时叠加，用于 mesh 风格
  if (theme.borderGradients && theme.borderGradients.length > 0) {
    // 彩虹色主题：叠加多个径向渐变
    theme.borderGradients.forEach(grad => {
      gradients.push(`radial-gradient(${grad.position}, ${grad.color} 0px, transparent 50%) border-box`);
    });
  }

  // 3. 基础边框颜色（border-box）：作为兜底底色，保证无渐变时仍有质感
  gradients.push(`linear-gradient(${theme.baseBorderColor} 0 100%) border-box`);
  return gradients.join(',\n\t\t\t\t');
}

/**
 * 生成发光层的box-shadow CSS
 * @param {Object} theme - 主题配置
 * @returns {string} CSS box-shadow 属性值
 */
function generateGlowShadow(theme) {
  // 无边框主题：不产生任何阴影
  if (theme && theme.name === 'none') {
    return 'none';
  }
  const shadows = [];
  const config = GLOW_BASE_CONFIG.glowShadows;
  const colors = theme.glowColors;

  // 内阴影（inset）：勾勒内缘与层次过渡
  config.forEach((shadow, index) => {
    const color = colors[index] || colors[colors.length - 1];
    const hsl = `hsl(${color.hue}deg ${color.saturation}% ${color.lightness}% / ${shadow.opacity}%)`;
    shadows.push(`inset 0 0 ${shadow.blur}px ${shadow.spread}px ${hsl}`);
  });

  // 外阴影（不带 inset）：在卡片外扩散，形成环境光/泛光
  config.forEach((shadow, index) => {
    const color = colors[index] || colors[colors.length - 1];
    const hsl = `hsl(${color.hue}deg ${color.saturation}% ${color.lightness}% / ${shadow.opacity}%)`;
    shadows.push(`0 0 ${shadow.blur}px ${shadow.spread}px ${hsl}`);
  });
  return shadows.join(', \n\t\t\t\t');
}

/**
 * 生成遮罩的conic-gradient CSS
 * @param {Object} maskConfig - 遮罩配置（borderMask 或 glowMask）
 * @returns {string} CSS mask-image 属性值
 */
function generateMask(maskConfig) {
  // 生成锥形渐变（conic-gradient）蒙版：
  // - 可见区：black；不可见：transparent（受 -webkit-mask/mask 使用时的规则影响）
  // - 通过 --pointer-deg 控制起始角，配合鼠标位置实时变化
  return `conic-gradient(from var(--pointer-deg, 45deg) at center, black ${maskConfig.visibleStart}%, transparent ${maskConfig.fadeStart}%, transparent ${maskConfig.fadeEnd}%, black ${maskConfig.visibleEnd}%)`;
}
