    this.paragraphOverlays = new Map(); // 存储段落覆盖层元素，key为 pageIndex_paragraphIndex
    this.bboxOverlays = new Map(); // 存储bbox覆盖层元素，key为 pageIndex_paragraphIndex
    this.isActive = false;

    // 事件回调
    this.onUpdate = options.onUpdate || null;
    this.onDelete = options.onDelete || null;

    // 保存summary-manager的引用，用于查询段落数据
    this.summaryManager = options.summaryManager || null;

    // 连接线状态
    this.hoveredVibeCardId = null; // 当前悬浮的 VibeCard ID
    this.hoveredBboxKey = null; // 当前悬浮的 bbox key

