  const nodeType = node.data?.nodeType;
  const nodeWidth = NODE_DIMENSIONS.getWidth(nodeType);

  // 设置当前节点位置
  // 左栏节点需要右对齐：实际 X = 传入的 X（右边缘）- 节点宽度
