// ==================== 网络错误关键词 ====================
const NETWORK_ERROR_PATTERNS = [
// 通用网络错误
'network', 'networkerror', 'fetch', 'econnrefused', 'econnreset', 'enotfound', 'etimedout', 'timeout', 'socket', 'dns',
// 连接相关
'connection refused', 'connection reset', 'connection failed', 'unable to connect', 'failed to fetch', 'load failed',
// 离线/不可达
'offline', 'unreachable', 'no internet',
// SSL/TLS
'ssl', 'certificate', 'cert_',
// HTTP 网络层错误
'err_network', 'err_connection', 'err_internet', 'ns_error_net',
// 中文关键词
'网络', '连接失败', '连接超时', '无法连接', '请求失败', '请求超时'];

// ==================== API 错误关键词 ====================
const API_ERROR_PATTERNS = ['401', '403', '404', '429', '500', '502', '503', '504', 'unauthorized', 'forbidden', 'not found', 'rate limit', 'too many requests', 'internal server error', 'bad gateway', 'service unavailable', 'gateway timeout', 'api token', 'api key', 'authentication',
// 中文关键词
'服务不可用', '服务器错误', '请求频率', '频率限制', '认证失败', '授权失败', 'token'];

// ==================== 文件错误关键词 ====================
const FILE_ERROR_PATTERNS = ['file not found', 'no such file', 'enoent', 'permission denied', 'eacces', 'eperm', 'is a directory', 'eisdir', 'not a file', 'ns_error_file', 'file_not_found', 'unrecognized_path',
// 中文关键词
'文件不存在', '文件未找到', '找不到文件', '权限不足', '无法读取', '无法写入'];

// ==================== 限制错误关键词 ====================
const LIMIT_ERROR_PATTERNS = ['limit exceeded', 'too large', '100m', '暂不支持', '太大', 'exceeds'];

// ==================== 解析错误关键词 ====================
const PARSE_ERROR_PATTERNS = ['json', 'parse error', 'syntax error', 'unexpected token', 'invalid', 'malformed',
// 中文关键词
'解析失败', '解析错误', '格式错误', '无效的'];

// ==================== 核心函数 ====================

/**
 * 根据错误信息判断错误类型
 * @param {Error|string} error - 错误对象或错误信息
 * @returns {string} ErrorType 枚举值
 */
function classifyError(error) {
  const message = (error?.message || String(error)).toLowerCase();

  // 按优先级检查错误类型
  if (matchesPatterns(message, NETWORK_ERROR_PATTERNS)) {
    return ErrorType.NETWORK;
  }
  if (matchesPatterns(message, API_ERROR_PATTERNS)) {
    return ErrorType.API;
  }
  if (matchesPatterns(message, FILE_ERROR_PATTERNS)) {
    return ErrorType.FILE;
  }
  if (matchesPatterns(message, PARSE_ERROR_PATTERNS)) {
    return ErrorType.PARSE;
  }

  // 检查是否是限制类错误
  if (matchesPatterns(message, LIMIT_ERROR_PATTERNS)) {
    return ErrorType.LIMIT;
  }

  // 检查是否是用户取消
  if (message.includes('cancel') || message.includes('abort')) {
    return ErrorType.CANCELLED;
  }
  return ErrorType.UNKNOWN;
}

/**
 * 获取用户友好的错误消息
 * @param {Error|string} error - 错误对象或错误信息
 * @param {string} lang - 语言 ('zh' | 'en')，默认 'zh'
 * @returns {string} 用户友好的错误消息
 */
function getUserFriendlyMessage(error, lang = 'zh') {
  const errorType = classifyError(error);
  const baseMessage = USER_MESSAGES[errorType]?.[lang] || USER_MESSAGES[ErrorType.UNKNOWN][lang];
  if (errorType !== ErrorType.UNKNOWN) {
    return baseMessage;
  }
  const rawMessage = (error?.message || String(error) || '').replace(/^Error:\s*/, '').trim();
  if (!rawMessage || rawMessage === '[object Object]') {
    return baseMessage;
  }
  return `${baseMessage}\n${rawMessage.slice(0, 180)}`;
}

/**
 * 创建标准化的错误结果对象
 * @param {Error|string} error - 原始错误
 * @param {Object} context - 上下文信息（可选）
 * @returns {Object} 标准化错误对象
 */
function createErrorResult(error, context = {}) {
  const errorType = classifyError(error);
  const originalMessage = error?.message || String(error);
  return {
    success: false,
    errorType,
    error: originalMessage,
    message: getUserFriendlyMessage(error, context.lang || 'zh'),
    timestamp: new Date().toISOString(),
    ...context
  };
}

/**
 * 判断是否为网络错误
 * @param {Error|string} error - 错误对象或错误信息
 * @returns {boolean}
 */
function isNetworkError(error) {
  return classifyError(error) === ErrorType.NETWORK;
}

/**
 * 判断是否为可重试的错误（网络错误、部分 API 错误）
 * @param {Error|string} error - 错误对象或错误信息
 * @returns {boolean}
 */
function isRetryableError(error) {
  const errorType = classifyError(error);
  if (errorType === ErrorType.NETWORK) {
    return true;
  }
  // 部分 API 错误可重试（429、5xx）
  if (errorType === ErrorType.API) {
    const message = (error?.message || String(error)).toLowerCase();
    return message.includes('429') || message.includes('500') || message.includes('502') || message.includes('503') || message.includes('504') || message.includes('rate limit');
  }
  return false;
}

// ==================== 辅助函数 ====================

/**
 * 检查消息是否匹配任一模式
 * @param {string} message - 错误消息（已转小写）
 * @param {string[]} patterns - 模式数组
 * @returns {boolean}
 */
function matchesPatterns(message, patterns) {
  return patterns.some(pattern => message.includes(pattern));
}

// ==================== 默认导出 ====================
/* harmony default export */ const error_handler = ({
  ErrorType,
  classifyError,
  getUserFriendlyMessage,
  createErrorResult,
  isNetworkError,
  isRetryableError
});
