  /**
   * 从 GitHub URL 中提取仓库名称（owner/repo 格式）
   * @param {string} url - GitHub 仓库 URL
   * @returns {string} 仓库名称，如 "owner/repo"
   */
  _extractRepoNameFromUrl(url) {
    try {
      // 支持多种 GitHub URL 格式：
      // https://github.com/owner/repo
      // https://github.com/owner/repo.git
      // https://github.com/owner/repo/tree/main
      // git@github.com:owner/repo.git
      const match = url.match(/github\.com[/:]([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:\/|$)/i);
      if (match) {
        return `${match[1]}/${match[2]}`;
      }
      return url; // 无法解析时返回原始 URL
    } catch (error) {
      console.warn('[Reader] 解析 GitHub URL 失败:', error);
      return url;
    }
  }

